{"command":"create","path":"/workspace/four_bit_pipelined_multiplier_tb.v","file_text":"`timescale 1ns/1ps

module four_bit_pipelined_multiplier_tb;
    reg clk;
    reg reset;
    reg [3:0] a;
    reg [3:0] b;
    wire [7:0] product;
    wire valid;

    four_bit_pipelined_multiplier uut (
        .clk(clk),
        .reset(reset),
        .a(a),
        .b(b),
        .product(product),
        .valid(valid)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        reset = 1;
        #10;
        reset = 0;

        // Test all possible input combinations
        for (integer i = 0; i < 16; i = i + 1) begin
            for (integer j = 0; j < 16; j = j + 1) begin
                a = i;
                b = j;
                #10;
                if (valid && product !== (a * b)) begin
                    $display("Test failed for a = %d, b = %d: expected %d, got %d", a, b, a * b, product);
                    $fatal;
                end
            end
        end

        $display("All tests passed.");
        $finish;
    end
endmodule"}

